	FOR VARIABLE="%SYS",  "DOCBOOK",  "ENSDEMO",  "ENSEMBLE", "HLEVAL1", "HSLIB", "SAMPLES",  "USER"
        {
	        if (VARIABLE = $NAMESPACE)
	        {
		        Quit $$$ERROR(6205, $NAMESPACE _ " is not a valid user namespace.")
	        }
	        elseif (' ##class(%SYS.Namespace).Exists($NAMESPACE))
	        {
		         Quit $$$ERROR(6205, $NAMESPACE _ " is not a valid user namespace.")
	        }
        }
