Quit rows


 If %query(pName) 
 { 
   set val = %query("ClassModifiedTime")
   set srcVal = %query(pName)
   Set intTime=$ZDATETIMEH(val, 3, 1)
   Set fileTime=$ZDATETIMEH(srcVal, 3, 1)
  // if date is greater OR date is same and time is greater
   if ( 
       ($p(intTime, ",", 1) > $p(fileTime, ",", 1)) || 
       (
         ($p(intTime, ",", 1) = $p(fileTime, ",", 1)) && ($p(intTime, ",", 2) > $p(fileTime, ",", 2))
       )
    )
   {	   
	   set srcVal = "<B><I>" _ srcVal _ "</I></B>"
   }
  Write srcVal
 } 
 Else 
 { 
   Write "<B><I> Not in SubVersion </I></B>"
 } 
 Quit $$$OK
